SELECT CASE WHEN YEAR(sale_date) < 2024 THEN 'before_2024' WHEN YEAR(sale_date) = 2024 THEN '2024' ELSE 'after_2024' END sale_cohort, CASE WHEN units >= 37 THEN 'high' WHEN units >= 14 THEN 'mid' ELSE 'low' END units_bucket, COUNT(*) num_store_sales FROM store_sales WHERE (product_id IN (1, 2, 4, 5) AND units = 11) OR sale_date >= '2023-07-01' GROUP BY 1, 2 HAVING MIN(units) >= 18 ORDER BY sale_cohort;
